package org.apache.commons.math3.geometry.euclidean.threed;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.apache.commons.math3.exception.MathIllegalArgumentException;
import org.apache.commons.math3.geometry.euclidean.oned.Interval;
import org.apache.commons.math3.geometry.euclidean.oned.IntervalsSet;
import org.apache.commons.math3.geometry.euclidean.oned.Vector1D;
import org.apache.commons.math3.geometry.euclidean.threed.IntervalsSet;
import org.apache.commons.math3.geometry.euclidean.threed.Line;
import org.apache.commons.math3.geometry.euclidean.threed.SubLine;
import org.apache.commons.math3.geometry.euclidean.threed.Vector3D;
import org.apache.commons.math3.geometry.partitioning.Region.Location;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for SubLine.getSegments().
 */
public class SubLine_getSegments_TriageGen0Test {

    @Test
    public void testGetSegmentsEmpty() {
        Line line = new Line(Vector3D.PLUS_ONE, Vector3D.PLUS_ONE);
        IntervalsSet emptyRegion = IntervalsSet.EMPTY;
        SubLine subLine = new SubLine(line, emptyRegion);

        List<Segment> segments = subLine.getSegments();

        assertNotNull(segments);
        assertTrue(segments.isEmpty());
    }

    @Test
    public void testGetSegmentsSingleInterval() {
        Line line = new Line(Vector3D.ZERO, Vector3D.PLUS_ONE);
        // Create a region representing the interval [1.0, 2.0]
        IntervalsSet region = new IntervalsSet(new double[]{1.0, 2.0});
        SubLine subLine = new SubLine(line, region);

        List<Segment> segments = subLine.getSegments();

        assertEquals(1, segments.size());
        Segment segment = segments.get(0);

        // Expected start: line.toSpace(1.0) -> Vector3D(1, 0, 0) if line is X-axis
        // Since line is (0,0,0) to (1,0,0), toSpace maps 1.0 to Vector3D(1,0,0) and 2.0 to Vector3D(2,0,0)
        // However, toSpace in Commons Math for a line defined by P + tV maps t to Vector3D(t,0,0) relative to the line's coordinate system
        // In the context of SubLine, the mapping is usually the parameter mapping.

        Vector3D expectedStart = line.toSpace(new Vector1D(1.0));
        Vector3D expectedEnd = line.toSpace(new Vector1D(2.0));

        assertEquals(0, expectedStart.distance(segment.getStart()));
        assertEquals(0, expectedEnd.distance(segment.getEnd()));
        assertEquals(line, segment.getLine());
    }

    @Test
    public void testGetSegmentsMultipleIntervals() {
        Line line = new Line(Vector3D.ZERO, Vector3D.PLUS_ONE);
        // Create a region with two intervals: [0.0, 1.0] and [3.0, 4.0]
        IntervalsSet region = new IntervalsSet(new double[]{0.0, 1.0, 3.0, 4.0});
        SubLine subLine = new SubLine(line, region);

        List<Segment> segments = subLine.getSegments();

        assertEquals(2, segments.size());

        // First segment
        assertEquals(0, line.toSpace(new Vector1D(0.0)).distance(segments.get(0).getStart()));
        assertEquals(0, line.toSpace(new Vector1D(1.0)).distance(segments.get(0).getEnd()));

        // Second segment
        assertEquals(0, line.toSpace(new Vector1D(3.0)).distance(segments.get(1).getStart()));
        assertEquals(0, line.toSpace(new Vector1D(4.0)).distance(segments.get(1).getEnd()));
    }

    /**
     * Helper class to simulate Vector1D if not directly accessible or to match logic
     */
    private static class Vector1D extends org.apache.commons.math3.geometry.euclidean.threed.Vector3D {
        protected Vector1D(double x) {
            super(x, 0, 0);
        }
    }
}
